const item = $input.first().json;
const body = item.body || item;
const rawMessage = (body.message || '').trim();
const channelId = String(body.channel_id || '');
const msgId = String(body.telegram_msg_id || '');

// 1. Mensaje vacio
if (!rawMessage) {
  return [{
    json: {
      is_valid: false,
      reason: 'Mensaje vacio',
      status: 'DESCARTADO',
      raw_message: rawMessage,
      channel_id: channelId,
      telegram_msg_id: msgId
    }
  }];
}

const upper = rawMessage.toUpperCase();

// 2. Descartar actualizaciones tipo TP HIT, SL HIT, etc.
const hitPatterns = [
  'TP HIT', 'TP1 HIT', 'TP2 HIT', 'TP3 HIT', 'TAKE PROFIT HIT',
  'SL HIT', 'STOP LOSS HIT', 'PIPS GAINED', 'RUNNING IN PROFIT',
  'SECURE PROFIT', 'CLOSE HALF', 'MOVE SL TO ENTRY', 'BREAKEVEN',
  'RESULT', 'RECAP', 'VIP', 'DISCOUNT', 'PROMO', 'CONTACT ME',
  'FREE ACCESS', 'JOIN NOW'
];

for (const p of hitPatterns) {
  if (upper.includes(p)) {
    return [{
      json: {
        is_valid: false,
        reason: `Detectado patron de actualizacion/publicidad: ${p}`,
        status: 'DESCARTADO',
        raw_message: rawMessage,
        channel_id: channelId,
        telegram_msg_id: msgId
      }
    }];
  }
}

// 3. Debe contener accion de trading (BUY o SELL)
const hasAction = /\b(BUY|SELL|COMPRA|VENTA)\b/i.test(upper);
if (!hasAction) {
  return [{
    json: {
      is_valid: false,
      reason: 'No contiene palabra clave de orden (BUY/SELL)',
      status: 'DESCARTADO',
      raw_message: rawMessage,
      channel_id: channelId,
      telegram_msg_id: msgId
    }
  }];
}

return [{
  json: {
    is_valid: true,
    raw_message: rawMessage,
    channel_id: channelId,
    telegram_msg_id: msgId
  }
}];

